    step("Cargo.lock 钉住版本:cargo update -p itoa --precise 1.0.5 把锁文件里的 itoa 回退到 1.0.5(满足 \"1\" 的要求);之后正常 cargo build,锁文件仍然是 1.0.5,即使 crates.io 上已有 1.0.18 也不会被自动升级;cargo update -p itoa 才把它升到 1.0.18,而 Cargo.toml 全程没有改动。", t=tl(S(4)), done=lidx(S(4), 'generate-lockfile', '正常 cargo build', 'cargo update -p itoa 之后'), kv=KV([['--precise', '回退到指定版本'], ['cargo build', '不升级锁定版本'], ['cargo update -p', '升级到满足要求的最新版']], ['cargo build'])),
    step("--precise 指定的版本必须满足 Cargo.toml 里的要求:把 itoa 钉到 0.4.8(不满足 \"^1\")会报 error: failed to select a version for the requirement `itoa = \"^1\"`。想换大版本得先改 Cargo.toml 里的要求。", t=tl(S(4)), mark=lidx(S(4), '--precise 到不满足'), kv=KV([['--precise 越界', '不满足要求 → 报错']], ['--precise 越界'])),
